import pandas as pd
import numpy as np

def test_frame_any_bool_categorical_unobserved():
    df = pd.DataFrame(
        {
            "g": pd.Categorical(["a", "a", "b"], categories=["a", "b", "c"]),
            "v": [True, False, True],
        }
    )
    result = df.groupby("g", observed=False).any()
    assert list(result.index) == ["a", "b", "c"]
    assert result["v"].dtype == np.dtype("bool")
    assert result.loc["c", "v"] == False
